/**
 * Full-file AST semantic comparison between base source (e.g. `git show base:file`) and head source.
 * Fail-closed (`outcome: 'blocked'`) if the TypeScript compiler is unavailable.
 *
 * @param {string} filePath
 * @param {string} baseSource
 * @param {string} headSource
 * @param {{ assertFunctionNames?: string[], activeWaivers?: any[], qaDir?: string, tsCompiler?: any, rulesConfig?: Record<string, any>, protectedGlobs?: string[], changesetContext?: any }} [options]
 */
export function compareSpecSourcesAst(filePath, baseSource, headSource, options = {}) {
  const {
    assertFunctionNames = ['expect*', 'assert*', 'verify*'],
    activeWaivers = [],
    qaDir,
    rulesConfig = {},
    protectedGlobs,
    changesetContext = null,
  } = options;

  /** @param {string} key */
  const canWaive = (key) => Boolean(isCoveredByWaiver({ file: filePath, title: key }, activeWaivers, 'diff'));
  const astOpts = {
    assertFunctionNames,
    qaDir,
    wrapInAsyncFn: false,
    ...('tsCompiler' in options ? { tsCompiler: options.tsCompiler } : {}),
  };

  const baseSum = analyzeSourceAst(filePath, baseSource || '', astOpts);
  const headSum = analyzeSourceAst(filePath, headSource || '', astOpts);

  if (baseSum.compilerUnavailable || headSum.compilerUnavailable) {
    const blockedMsg = `[Healer Diff Guard Blocked] ${filePath}: TypeScript compiler unavailable; fail-closed instead of skipping AST semantic diff guard.`;
    return {
      ok: false,
      blocked: true,
      outcome: 'blocked',
      findings: [{ code: 'AITEST-BLOCKED', severity: 'error', file: filePath, message: blockedMsg }],
      violations: [blockedMsg],
    };
  }

  const evalRes = evaluateDiffRules({
    file: filePath,
    baseSum,
    headSum,
    baseSource: baseSource || '',
    headSource: headSource || '',
    canWaive,
    assertFunctionNames,
    rulesConfig,
    protectedGlobs,
    changesetContext,
    isDiffTextMode: false,
  });

  return {
    ok: evalRes.ok,
    blocked: false,
    outcome: evalRes.ok ? 'pass' : 'fail',
    findings: evalRes.findings,
    violations: evalRes.violations,
  };
}

/**
 * Checks whether branch-new specs/tests preserve at least one non-tautological `>= S2` assertion per test block (`WU-04`).
 * Empty specs (`blocks.length === 0`) NEVER satisfy the floor (`v6.2.1`).
 * @param {import('./parser.mjs').AstSummary | null | undefined} headSum
 * @param {Set<string> | null} baselineTestTitles
 * @param {boolean} isBaselineNewSpec
 * @returns {boolean}
 */
function meetsBranchNewAssertionFloor(headSum, baselineTestTitles, isBaselineNewSpec) {
  if (!headSum) return false;
  const blocks = headSum.testBlocks || [];
  if (isBaselineNewSpec) {
    if (blocks.length === 0) return false;
    return blocks.every((tb) => (tb.assertions || []).some((a) => !a.isTautology && a.tier >= 2));
  }
  if (!baselineTestTitles) return false;
  const branchNewBlocks = blocks.filter((tb) => !baselineTestTitles.has(tb.title));
  if (branchNewBlocks.length === 0) return true;
  return branchNewBlocks.every((tb) => (tb.assertions || []).some((a) => !a.isTautology && a.tier >= 2));
}

/**
 * Commit-level multi-file AST changeset comparison (`compareChangesetAst`).
 * Parses every changed spec file in the commit together so rules can inspect cross-file context
 * (e.g., tests split or moved across spec files in the same commit).
 *
 * @param {Array<{ filePath: string, baseSource: string, headSource: string, isBaselineNewSpec?: boolean, baselineTestTitles?: Set<string> | null }>} fileChanges
 * @param {{ assertFunctionNames?: string[], activeWaivers?: any[], qaDir?: string, tsCompiler?: any, rulesConfig?: Record<string, any>, protectedGlobs?: string[], enforceProjectScopes?: boolean }} [options]
 */
export function compareChangesetAst(fileChanges, options = {}) {
  const {
    assertFunctionNames = ['expect*', 'assert*', 'verify*'],
    activeWaivers = [],
    qaDir,
    rulesConfig = {},
    protectedGlobs,
    enforceProjectScopes = false,
  } = options;

  const astOpts = {
    assertFunctionNames,
    qaDir,
    wrapInAsyncFn: false,
    ...('tsCompiler' in options ? { tsCompiler: options.tsCompiler } : {}),
  };

  const projectScopes = enforceProjectScopes && qaDir ? parsePlaywrightProjectScopes(qaDir) : null;
  const parsedEntries = (fileChanges || []).map((entry) => {
    const baseSum = analyzeSourceAst(entry.filePath, entry.baseSource || '', astOpts);
    const headSum = analyzeSourceAst(entry.filePath, entry.headSource || '', astOpts);
    const isBaselineNewSpec = Boolean(entry.isBaselineNewSpec);
    const baselineTestTitles = entry.baselineTestTitles || null;
    const exemptBranchNewRegression =
      (isBaselineNewSpec || baselineTestTitles !== null) &&
      meetsBranchNewAssertionFloor(headSum, baselineTestTitles, isBaselineNewSpec);
    const isExecutableSpec =
      !enforceProjectScopes || !qaDir
        ? /\.(?:spec|test)\.[jt]sx?$/i.test(entry.filePath)
        : isExecutablePlaywrightSpecPath(qaDir, entry.filePath, projectScopes);
    return {
      filePath: entry.filePath,
      baseSource: entry.baseSource || '',
      headSource: entry.headSource || '',
      baseSum,
      headSum,
      isBaselineNewSpec,
      baselineTestTitles,
      exemptBranchNewRegression,
      isExecutableSpec,
    };
  });

  const changesetContext = {
    entries: parsedEntries,
  };

  /** @type {Array<Record<string, any>>} */
  const allFindings = [];
  /** @type {string[]} */
  const allViolations = [];
  let blocked = false;

  for (const entry of parsedEntries) {
    if (entry.baseSum.compilerUnavailable || entry.headSum.compilerUnavailable) {
      blocked = true;
      const blockedMsg = `[Healer Diff Guard Blocked] ${entry.filePath}: TypeScript compiler unavailable; fail-closed instead of skipping AST semantic diff guard.`;
      allFindings.push({ code: 'AITEST-BLOCKED', severity: 'error', file: entry.filePath, message: blockedMsg });
      allViolations.push(blockedMsg);
      continue;
    }

    const exemptScaffoldRemoval =
      isScaffoldOnlySpec(entry.baseSum) &&
      (entry.headSum.testBlocks || []).length === 0 &&
      hasRealNonScaffoldSpec(qaDir, parsedEntries, entry.filePath, astOpts);

    /** @param {string} key */
    const canWaive = (key) => Boolean(isCoveredByWaiver({ file: entry.filePath, title: key }, activeWaivers, 'diff'));
    const evalRes = evaluateDiffRules({
      file: entry.filePath,
      baseSum: entry.baseSum,
      headSum: entry.headSum,
      baseSource: entry.baseSource,
      headSource: entry.headSource,
      canWaive,
      assertFunctionNames,
      rulesConfig,
      protectedGlobs,
      changesetContext,
      isBaselineNewSpec: entry.isBaselineNewSpec,
      baselineTestTitles: entry.baselineTestTitles,
      exemptBranchNewRegression: entry.exemptBranchNewRegression,
      exemptScaffoldRemoval,
      isDiffTextMode: false,
    });
    allFindings.push(...evalRes.findings);
    allViolations.push(...evalRes.violations);
  }

  const uniqueViolations = [...new Set(allViolations)];
  return {
    ok: !blocked && uniqueViolations.length === 0,
    blocked,
    outcome: blocked ? 'blocked' : uniqueViolations.length === 0 ? 'pass' : 'fail',
    findings: allFindings,
    violations: uniqueViolations,
  };
}

/**
 * Full-file + Git-diff Layer 3 Semantic Guard (`G-01..G-09`).
 * Compares FULL `git show <diffBase>:<file>` against live disk content across the entire changeset.
 * @param {string} qaDir
 * @param {string} diffBase
 * @param {{ activeWaivers?: Array<Record<string, any>>, tsCompiler?: any, baselineRef?: string | null, explicitBase?: boolean, trustContext?: import('./trust-context.mjs').TrustContext, env?: Record<string, string | undefined> }} [options]
 * @returns {{ ok: boolean, status: 'pass' | 'fail' | 'blocked', findings: Array<Record<string, any>>, violations: string[] }}
 */
export function runGitDiffGuard(qaDir, diffBase, options = {}) {
  const gitRoot = resolveGitRoot(qaDir);
  if (!gitRoot) {
    return {
      ok: false,
      status: 'blocked',
      findings: [],
      violations: [`[Healer Diff Guard] Directory "${qaDir}" is not inside a Git repository; fail-closed.`],
    };
  }

  const changedInfo = listChangedFilesUnderDir(gitRoot, diffBase, qaDir);
  if (!changedInfo.ok) {
    return {
      ok: false,
      status: 'blocked',
      findings: [],
      violations: [`[Healer Diff Guard] git diff "${diffBase}" failed: ${changedInfo.error}`],
    };
  }

  const cfg = loadAitestConfig(qaDir);
  const activeWaivers = options.activeWaivers || [];
  const violations = [...validateAssertFunctionNames(cfg.assertFunctionNames)];
  /** @type {Array<Record<string, any>>} */
  const findings = [];

  const baselineRes = resolveValidatedWorkspaceBaselineRef(qaDir, gitRoot, {
    explicitBase: Boolean(options.explicitBase),
    ...(options.baselineRef !== undefined ? { explicitBaselineRef: options.baselineRef } : {}),
    trustContext: options.trustContext,
    env: options.env || process.env,
  });
  if (baselineRes.blocked) {
    const msg = baselineRes.error || '[Baseline Tamper Blocked] Invalid .aitest/baseline-ref.';
    return {
      ok: false,
      status: 'blocked',
      findings: [{ code: 'AITEST-G101', severity: 'error', file: '.aitest/baseline-ref', message: msg }],
      violations: [msg],
    };
  }
  const validBaselineRef = baselineRes.ref;
  const projectScopes = parsePlaywrightProjectScopes(qaDir);

  const allChangedRelFromGitRoot = [
    ...changedInfo.changed.map((c) => ({ rel: c.path, status: c.status, oldRel: c.oldPath || c.path })),
    ...changedInfo.untracked.map((p) => ({ rel: p, status: 'U', oldRel: null })),
  ];

  const realQaDir = (() => {
    try {
      return typeof fs.realpathSync.native === 'function' ? fs.realpathSync.native(qaDir) : fs.realpathSync(qaDir);
    } catch {
      return path.resolve(qaDir);
    }
  })();

  /** @type {Array<{ filePath: string, baseSource: string, headSource: string, isBaselineNewSpec?: boolean, baselineTestTitles?: Set<string> | null }>} */
  const specChanges = [];

  for (const item of allChangedRelFromGitRoot) {
    const absPath = path.join(gitRoot, item.rel);
    const relInsideQa = path.relative(realQaDir, absPath).replace(/\\/g, '/');
    if (
      /^(reports|playwright-report|test-results|knowledge|\.aitest\/runs|\.aitest\/heals|\.aitest\/jobs|node_modules)\//.test(
        relInsideQa
      )
    ) {
      continue;
    }

    /** @param {string} key */
    const canWaive = (key) => Boolean(isCoveredByWaiver({ file: relInsideQa, title: key }, activeWaivers, 'diff'));

    // G-08: Prevent hiding an executable spec by moving/renaming it outside active Playwright testMatch/testDir (`F44`, `F45`, `F55`)
    if (item.status.startsWith('R') && item.oldRel) {
      const oldRelInsideQa = path.relative(realQaDir, path.join(gitRoot, item.oldRel)).replace(/\\/g, '/');
      if (
        /^tests\/.*\.(?:spec|test)\.[jt]sx?$/i.test(oldRelInsideQa) &&
        !isExecutablePlaywrightSpecPath(qaDir, relInsideQa, projectScopes)
      ) {
        const msg = `${oldRelInsideQa}: spec renamed/moved outside executable tests directory to non-executable path "${relInsideQa}" (testMatch/testDir conservation violation).`;
        findings.push({ code: 'AITEST-G101', severity: 'error', file: relInsideQa, message: msg });
        violations.push(`[Healer Diff Guard][AITEST-G101] ${msg}`);
        continue;
      }
    }

    // 1. Check protected file path regardless of extension or non-ASCII parent path
    if (isProtectedDiffPath(relInsideQa, cfg.governance?.protected) && !canWaive('protected-file')) {
      const msg = `${relInsideQa}: modification to protected governance/config file is forbidden without human approval.`;
      findings.push({ code: 'AITEST-G101', severity: 'error', file: relInsideQa, message: msg });
      violations.push(`[Healer Diff Guard][AITEST-G101] ${msg}`);
      continue;
    }

    // 2. Collect TS/JS/MJS files for commit-level changeset AST comparison
    if (/\.(ts|tsx|js|jsx|mjs)$/i.test(relInsideQa)) {
      const baseSource =
        item.oldRel && item.status !== 'A' && item.status !== 'U'
          ? getFileAtGitRef(gitRoot, diffBase, item.oldRel) || ''
          : '';
      const headSource =
        fs.existsSync(absPath) && fs.statSync(absPath).isFile() ? fs.readFileSync(absPath, 'utf8') : '';

      let isBaselineNewSpec = false;
      /** @type {Set<string> | null} */
      let baselineTestTitles = null;
      if (validBaselineRef && /\.(?:spec|test)\.[jt]s$/i.test(relInsideQa)) {
        const baselineLookupRel = item.oldRel || item.rel;
        const baselineContent = getFileAtGitRef(gitRoot, validBaselineRef, baselineLookupRel);
        if (baselineContent === null) {
          isBaselineNewSpec = true;
        } else {
          const baseAstOpts = {
            assertFunctionNames: cfg.assertFunctionNames,
            qaDir,
            wrapInAsyncFn: false,
            ...('tsCompiler' in options ? { tsCompiler: options.tsCompiler } : {}),
          };
          const baselineSum = analyzeSourceAst(relInsideQa, baselineContent, baseAstOpts);
          if (baselineSum.usedAst && !baselineSum.compilerUnavailable) {
            baselineTestTitles = new Set((baselineSum.testBlocks || []).map((tb) => tb.title));
          }
        }
      }

      specChanges.push({
        filePath: relInsideQa,
        baseSource,
        headSource,
        isBaselineNewSpec,
        baselineTestTitles,
      });
    }
  }

  let blocked = false;
  if (specChanges.length > 0) {
    const cmp = compareChangesetAst(specChanges, {
      assertFunctionNames: cfg.assertFunctionNames,
      activeWaivers,
      qaDir,
      enforceProjectScopes: true,
      rulesConfig: cfg.rules || {},
      protectedGlobs: cfg.governance?.protected,
      ...('tsCompiler' in options ? { tsCompiler: options.tsCompiler } : {}),
    });
    if (cmp.blocked) blocked = true;
    findings.push(...cmp.findings);
    violations.push(...cmp.violations);
  }

  // Layer 3 Product-Side Dieselgate Guard (`AITEST-G117`): block test-traffic special-casing outside `qa/`
  if (isRuleEnabled('AITEST-G117', cfg.rules || {})) {
    const repoChanged = listChangedFilesUnderDir(gitRoot, diffBase, gitRoot);
    if (repoChanged.ok) {
      const repoItems = [
        ...repoChanged.changed.map((c) => ({ rel: c.path, status: c.status, oldRel: c.oldPath || c.path })),
        ...repoChanged.untracked.map((p) => ({ rel: p, status: 'U', oldRel: null })),
      ];
      for (const item of repoItems) {
        const normRel = item.rel.replace(/\\/g, '/');
        if (!/\.(?:ts|tsx|js|jsx|mjs|cjs)$/i.test(normRel)) continue;
        const absProd = path.join(gitRoot, item.rel);
        const relFromQa = path.relative(realQaDir, absProd).replace(/\\/g, '/');
        if (!relFromQa.startsWith('..')) continue;
        if (
          /^(?:qa|test|tests|bench|scripts|reports|knowledge|\.aitest|node_modules)\//i.test(normRel) ||
          /\/(?:qa|test|tests|bench|reports|knowledge|\.aitest|node_modules)\//i.test(normRel)
        ) {
          continue;
        }
        if (/\.(?:spec|test)\.[jt]sx?$/i.test(normRel)) continue;
        if (isCoveredByWaiver({ file: normRel, title: 'AITEST-G117' }, activeWaivers, 'diff')) continue;
        const baseProd =
          item.oldRel && item.status !== 'A' && item.status !== 'U'
            ? getFileAtGitRef(gitRoot, diffBase, item.oldRel) || ''
            : '';
        const headProd =
          fs.existsSync(absProd) && fs.statSync(absProd).isFile() ? fs.readFileSync(absProd, 'utf8') : '';
        const dgRes = evaluateProductFileAst(normRel, baseProd, headProd, {
          qaDir,
          ...('tsCompiler' in options ? { tsCompiler: options.tsCompiler } : {}),
        });
        findings.push(...dgRes.findings);
        violations.push(...dgRes.violations);
      }
    }
  }

  const unique = [...new Set(violations)];
  return {
    ok: !blocked && unique.length === 0,
    status: blocked ? 'blocked' : unique.length === 0 ? 'pass' : 'fail',
    findings,
    violations: unique,
  };
}
